namespace sv_482a73b02bd24ca5a4db7a38896e1eff.Services;

public record Channel(int Id, string Name, string Description, int UnreadCount);
public record Message(int Id, int ChannelId, string Author, string Content, DateTime SentAt, int? ReplyToId, List<Reaction> Reactions);
public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

@using sv_482a73b02bd24ca5a4db7a38896e1eff.Services

<div class="channel-sidebar">
    <div class="sidebar-header">
        <h5 class="mb-0 fw-bold text-white">Channels</h5>
    </div>
    <ul class="channel-list list-unstyled mb-0">
        @foreach (var channel in Channels)
        {
            <li class="channel-item @(channel.Id == ActiveChannelId ? "active" : "")"
                @onclick="() => OnChannelSelected.InvokeAsync(channel.Id)">
                <div class="d-flex justify-content-between align-items-start">
                    <div class="channel-info text-truncate me-2">
                        <span class="channel-name fw-semibold"># @channel.Name</span>
                        @if (!string.IsNullOrWhiteSpace(channel.Description))
                        {
                            <div class="channel-desc text-truncate small">@channel.Description</div>
                        }
                    </div>
                    @if (channel.UnreadCount > 0)
                    {
                        <span class="badge bg-danger rounded-pill">@channel.UnreadCount</span>
                    }
                </div>
            </li>
        }
    </ul>
</div>

@code {
    [Parameter, EditorRequired]
    public List<Channel> Channels { get; set; } = [];

    [Parameter]
    public int? ActiveChannelId { get; set; }

    [Parameter]
    public EventCallback<int> OnChannelSelected { get; set; }
}

@using sv_482a73b02bd24ca5a4db7a38896e1eff.Services

<div class="message-item" @onmouseenter="() => showActions = true" @onmouseleave="() => { showActions = false; showEmojiPicker = false; }">
    <div class="d-flex justify-content-between align-items-start">
        <div>
            <span class="fw-bold">@Message.Author</span>
            <span class="text-muted small ms-2">@FormatRelativeTime(Message.SentAt)</span>
        </div>
        @if (showActions)
        {
            <div class="message-actions d-flex gap-1">
                <button class="btn btn-sm btn-outline-secondary py-0 px-1" title="React" @onclick="ToggleEmojiPicker">
                    😀
                </button>
                <button class="btn btn-sm btn-outline-secondary py-0 px-1" title="Reply" @onclick="() => OnOpenThread.InvokeAsync(Message.Id)">
                    💬
                </button>
            </div>
        }
    </div>

    <div class="message-content mt-1">@Message.Content</div>

    @if (Message.Reactions.Count > 0)
    {
        <div class="reactions d-flex flex-wrap gap-1 mt-1">
            @foreach (var reaction in Message.Reactions)
            {
                <button class="btn btn-sm btn-outline-secondary reaction-badge py-0 px-1"
                        title="@string.Join(", ", reaction.Users)"
                        @onclick="() => OnReact.InvokeAsync((Message.Id, reaction.Emoji))">
                    @reaction.Emoji @reaction.Users.Count
                </button>
            }
        </div>
    }

    @if (showEmojiPicker)
    {
        <div class="emoji-picker d-flex gap-1 mt-1 p-1 border rounded bg-white shadow-sm">
            @foreach (var emoji in commonEmojis)
            {
                <button class="btn btn-sm btn-light px-1 py-0"
                        @onclick="() => SelectEmoji(emoji)">@emoji</button>
            }
        </div>
    }

    @if (ThreadInfo is not null)
    {
        <button class="btn btn-sm btn-link text-decoration-none p-0 mt-1"
                @onclick="() => OnOpenThread.InvokeAsync(Message.Id)">
            💬 @ThreadInfo.ReplyCount @(ThreadInfo.ReplyCount == 1 ? "reply" : "replies")
        </button>
    }
</div>

@code {
    private bool showActions;
    private bool showEmojiPicker;
    private static readonly string[] commonEmojis = ["👍", "❤️", "😂", "🎉", "🤔", "👀"];

    [Parameter, EditorRequired]
    public Message Message { get; set; } = default!;

    [Parameter]
    public ThreadSummary? ThreadInfo { get; set; }

    [Parameter]
    public EventCallback<int> OnOpenThread { get; set; }

    [Parameter]
    public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private void ToggleEmojiPicker() => showEmojiPicker = !showEmojiPicker;

    private async Task SelectEmoji(string emoji)
    {
        showEmojiPicker = false;
        await OnReact.InvokeAsync((Message.Id, emoji));
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalSeconds < 60) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }
}

@using sv_482a73b02bd24ca5a4db7a38896e1eff.Services

<div class="thread-panel d-flex flex-column h-100 border-start">
    <div class="thread-header d-flex justify-content-between align-items-center p-3 border-bottom bg-light">
        <h6 class="mb-0 fw-bold">Thread</h6>
        <button class="btn btn-sm btn-outline-secondary" @onclick="OnClose">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="root-message p-3 border-bottom bg-light bg-opacity-50">
            <div>
                <span class="fw-bold">@RootMessage.Author</span>
                <span class="text-muted small ms-2">@RootMessage.SentAt.ToString("MMM d, h:mm tt")</span>
            </div>
            <div class="mt-1">@RootMessage.Content</div>
        </div>
    }

    <div class="thread-messages flex-grow-1 overflow-auto p-3">
        @foreach (var reply in Replies)
        {
            <div class="thread-reply mb-3">
                <div>
                    <span class="fw-bold">@reply.Author</span>
                    <span class="text-muted small ms-2">@FormatRelativeTime(reply.SentAt)</span>
                </div>
                <div class="mt-1">@reply.Content</div>
            </div>
        }
    </div>

    <MessageInput Placeholder="Reply in thread…" ButtonText="Reply" OnSend="OnSendReply" />
</div>

@code {
    [Parameter]
    public Message? RootMessage { get; set; }

    [Parameter]
    public List<Message> Replies { get; set; } = [];

    [Parameter]
    public EventCallback OnClose { get; set; }

    [Parameter]
    public EventCallback<string> OnSendReply { get; set; }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalSeconds < 60) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }
}

