@using sv_482a73b02bd24ca5a4db7a38896e1eff.Services

<div class="thread-panel d-flex flex-column h-100 border-start">
    <div class="thread-header d-flex justify-content-between align-items-center p-3 border-bottom bg-light">
        <h6 class="mb-0 fw-bold">Thread</h6>
        <button class="btn btn-sm btn-outline-secondary" @onclick="OnClose">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="root-message p-3 border-bottom bg-light bg-opacity-50">
            <div>
                <span class="fw-bold">@RootMessage.Author</span>
                <span class="text-muted small ms-2">@RootMessage.SentAt.ToString("MMM d, h:mm tt")</span>
            </div>
            <div class="mt-1">@RootMessage.Content</div>
        </div>
    }

    <div class="thread-messages flex-grow-1 overflow-auto p-3">
        @foreach (var reply in Replies)
        {
            <div class="thread-reply mb-3">
                <div>
                    <span class="fw-bold">@reply.Author</span>
                    <span class="text-muted small ms-2">@FormatRelativeTime(reply.SentAt)</span>
                </div>
                <div class="mt-1">@reply.Content</div>
            </div>
        }
    </div>

    <MessageInput Placeholder="Reply in thread…" ButtonText="Reply" OnSend="OnSendReply" />
</div>

@code {
    [Parameter]
    public Message? RootMessage { get; set; }

    [Parameter]
    public List<Message> Replies { get; set; } = [];

    [Parameter]
    public EventCallback OnClose { get; set; }

    [Parameter]
    public EventCallback<string> OnSendReply { get; set; }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalSeconds < 60) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }
}

