+                {
+                    <div class="text-center text-muted py-2">
+                        <span class="spinner-border spinner-border-sm me-1"></span> Loading older messages…
+                    </div>
+                }
+                @foreach (var msg in messages)
+                {
+                    <MessageItem Message="msg"
+                                 ThreadInfo="GetThreadInfo(msg.Id)"
+                                 OnOpenThread="OpenThread"
+                                 OnReact="HandleReaction" />
+                }
+            </div>
+
+            <MessageInput Placeholder="Message #@selectedChannel.Name"
+                          ButtonText="Send"
+                          OnSend="SendMessage" />
+        }
+        else
+        {
+            <div class="d-flex align-items-center justify-content-center h-100 text-muted">
+                <div class="text-center">
+                    <h4>Welcome to Chat</h4>
+                    <p>Select a channel to start messaging</p>
+                </div>
+            </div>
+        }
+    </div>
+
+    @if (isThreadOpen)
+    {
+        <div class="chat-thread">
+            <ThreadPanel RootMessage="threadRootMessage"
+                         Replies="threadReplies"
+                         OnClose="CloseThread"
+                         OnSendReply="SendThreadReply" />
+        </div>
+    }
+</div>
+
+@code {
+    private List<Channel> channels = [];
+    private Channel? selectedChannel;
+    private int? selectedChannelId;
+    private List<Message> messages = [];
+    private Dictionary<int, ThreadSummary> threadSummaries = new();
+
+    private bool isThreadOpen;
+    private int? activeThreadRootId;
+    private Message? threadRootMessage;
+    private List<Message> threadReplies = [];
+
+    private bool isLoadingMore;
+    private bool hasMoreMessages = true;
+    private const int PageSize = 30;
+
+    protected override async Task OnInitializedAsync()
+    {
+        channels = await ChatService.GetChannelsAsync();
+        if (channels.Count > 0)
+        {
+            await SelectChannel(channels[0].Id);
+        }
+    }
+
+    private async Task SelectChannel(int channelId)
+    {
+        selectedChannelId = channelId;
+        selectedChannel = channels.FirstOrDefault(c => c.Id == channelId);
+        messages = [];
+        threadSummaries = new();
+        hasMoreMessages = true;
+
+        var loaded = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
+        messages = loaded;
+        hasMoreMessages = loaded.Count >= PageSize;
+
+        BuildThreadSummaries();
+        await ChatService.MarkChannelReadAsync(channelId);
+
+        // Refresh channel list to update unread counts
+        channels = await ChatService.GetChannelsAsync();
+
+        CloseThreadSync();
+    }
+
+    private async Task HandleScroll()
+    {
+        // Triggered on scroll — loads older messages when near top
+        if (isLoadingMore || !hasMoreMessages || selectedChannelId is null) return;
+
+        isLoadingMore = true;
+        var older = await ChatService.GetMessagesAsync(selectedChannelId.Value, messages.Count, PageSize);
+        if (older.Count > 0)
+        {
+            messages.InsertRange(0, older);
+            BuildThreadSummaries();
+        }
+        hasMoreMessages = older.Count >= PageSize;
+        isLoadingMore = false;
+    }
+
+    private async Task SendMessage(string content)
+    {
+        if (selectedChannelId is null) return;
+        var msg = await ChatService.SendMessageAsync(selectedChannelId.Value, content, null);
+        messages.Add(msg);
+    }
+
+    private async Task OpenThread(int rootMessageId)
+    {
+        activeThreadRootId = rootMessageId;
+        threadRootMessage = messages.FirstOrDefault(m => m.Id == rootMessageId);
+        threadReplies = await ChatService.GetThreadAsync(rootMessageId);
+        isThreadOpen = true;
+    }
+
+    private void CloseThreadSync()
+    {
+        isThreadOpen = false;
+        activeThreadRootId = null;
+        threadRootMessage = null;
+        threadReplies = [];
+    }
+
+    private Task CloseThread()
+    {
+        CloseThreadSync();
+        return Task.CompletedTask;
+    }
+
+    private async Task SendThreadReply(string content)
+    {
+        if (selectedChannelId is null || activeThreadRootId is null) return;
+        var reply = await ChatService.SendMessageAsync(selectedChannelId.Value, content, activeThreadRootId.Value);
+        threadReplies.Add(reply);
+
+        // Update thread summary
+        if (threadSummaries.TryGetValue(activeThreadRootId.Value, out var existing))
+        {
+            threadSummaries[activeThreadRootId.Value] = existing with
+            {
+                ReplyCount = existing.ReplyCount + 1,
+                LastReplyAt = reply.SentAt
+            };
+        }
+        else
+        {
+            threadSummaries[activeThreadRootId.Value] = new ThreadSummary(activeThreadRootId.Value, 1, reply.SentAt);
+        }
+    }
+
+    private async Task HandleReaction((int MessageId, string Emoji) args)
+    {
+        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
+
+        // Refresh the affected message's reactions by reloading messages
+        if (selectedChannelId is not null)
+        {
+            var refreshed = await ChatService.GetMessagesAsync(selectedChannelId.Value, 0, messages.Count);
+            messages = refreshed;
+        }
+    }
+
+    private ThreadSummary? GetThreadInfo(int messageId) =>
+        threadSummaries.GetValueOrDefault(messageId);
+
+    private void BuildThreadSummaries()
+    {
+        // Find messages that are thread starters (have replies pointing to them)
+        var replyGroups = messages
+            .Where(m => m.ReplyToId is not null)
+            .GroupBy(m => m.ReplyToId!.Value);
+
+        foreach (var group in replyGroups)
+        {
+            var replies = group.ToList();
+            threadSummaries[group.Key] = new ThreadSummary(
+                group.Key,
+                replies.Count,
+                replies.Max(r => r.SentAt));
+        }
+    }
+}
+

toolArgs.file_text:
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
}

/* Sidebar */
.chat-sidebar {
    width: 20%;
    min-width: 200px;
    flex-shrink: 0;
}

::deep .channel-sidebar {
    height: 100%;
    background-color: #2c2f33;
    color: #dcddde;
    display: flex;
    flex-direction: column;
}

::deep .sidebar-header {
    padding: 1rem;
    border-bottom: 1px solid rgba(255,255,255,0.1);
}

::deep .channel-list {
    overflow-y: auto;
    flex-grow: 1;
}

::deep .channel-item {
    padding: 0.5rem 1rem;
    cursor: pointer;
    transition: background-color 0.15s;
}

::deep .channel-item:hover {
    background-color: rgba(255,255,255,0.08);
}

::deep .channel-item.active {
    background-color: rgba(255,255,255,0.15);
}

::deep .channel-name {
    color: #fff;
}

::deep .channel-desc {
    color: #8e9297;
}

/* Main message area */
.chat-main {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
    background: #f8f9fa;
}

.chat-main.thread-open {
    /* Main area shrinks when thread is open */
}

::deep .message-list {
    flex-grow: 1;
    overflow-y: auto;
}

::deep .message-item {
    padding: 0.5rem 0;
    border-radius: 4px;
    position: relative;
}

::deep .message-item:hover {
    background-color: rgba(0,0,0,0.03);
}

::deep .message-actions {
    position: absolute;
    top: 0.25rem;
    right: 0.25rem;
}

::deep .reaction-badge {
    font-size: 0.8rem;
    border-radius: 12px;
}

::deep .emoji-picker {
    position: absolute;
    z-index: 10;
    font-size: 1.2rem;
}

/* Thread panel */
.chat-thread {
    width: 25%;
    min-width: 250px;
    flex-shrink: 0;
    background: #fff;
}

::deep .thread-panel {
    height: 100%;
}

::deep .thread-messages {
    overflow-y: auto;
}

::deep .thread-reply {
    padding-bottom: 0.5rem;
    border-bottom: 1px solid #eee;
}

